import { useState, type CSSProperties } from 'react'
import { Check, ChevronRight, Loader2 } from 'lucide-react'
import { cn } from '@/lib/utils'
import { PROFILES, type AgentStep, type DrugProfile } from '@/lib/pipeline'
import { useRun, type TraceItem } from '@/lib/run-store'
import { LANE_COLORS } from './lanes'
import { StatusIcon } from './pieces'

/** Apple-style spring { duration: 0.55, bounce: 0.3 } sampled to linear(): 4.6% overshoot, settles in ~800ms. */
const SPRING = 'linear(0,0.04,0.139,0.268,0.407,0.542,0.665,0.77,0.856,0.923,0.972,1.007,1.029,1.041,1.046,1.045,1.042,1.036,1.03,1.024,1.018,1.013,1.008,1.005,1.002,1,0.999,0.998,0.998,0.998,1)'
const EASE_OUT = 'cubic-bezier(0.23, 1, 0.32, 1)'

/** What each agent does, in order. Each trace step fills one row; the profile itself is the last. */
const PHASES: { type: AgentStep['type'] | 'profile'; label: string }[] = [
  { type: 'thinking', label: 'Hypothesis' },
  { type: 'tool_call', label: 'Open Targets query' },
  { type: 'tool_result', label: 'Target evidence' },
  { type: 'profile', label: 'Profile' },
]

/** The five profile agents, one card each. */
export function ProfileGrid() {
  const { state } = useRun()
  const steps = state.trace.filter((t) => t.stage === 'profiles')
  // Whatever had already happened when this grid mounted renders still, so revisiting the page never replays it.
  const [seen] = useState(() => ({
    started: new Set(steps.map((t) => t.lane)),
    written: new Set(state.profiles.map((p) => p.lane)),
  }))
  return (
    <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-5">
      <p role="status" className="sr-only">{state.profiles.length} of {PROFILES.length} profiles written</p>
      {PROFILES.map((p) => {
        const mine = steps.filter((t) => t.lane === p.lane)
        const profile = state.profiles.find((x) => x.lane === p.lane)
        if (!mine.length && !profile) return <Slot key={p.lane} lane={p.lane} name={p.name} />
        return (
          <AgentCard
            key={p.lane}
            lane={p.lane}
            name={p.name}
            steps={mine}
            profile={profile}
            running={state.stages.profiles === 'running'}
            enter={!seen.started.has(p.lane) && !seen.written.has(p.lane)}
            reveal={!seen.written.has(p.lane)}
          />
        )
      })}
    </div>
  )
}

function Diamond({ lane, faded }: { lane: number; faded?: boolean }) {
  // Same mark as this profile's point in the DRKG embedding (stage 03).
  return <span aria-hidden className={cn('mt-1.5 size-2.5 shrink-0 rotate-45 rounded-[2px]', faded && 'opacity-35')} style={{ background: LANE_COLORS[lane] }} />
}

/** Where a card lands before its agent starts. */
function Slot({ lane, name }: { lane: number; name: string }) {
  return (
    <div className="flex min-h-[29rem] flex-col rounded-xl border border-dashed border-foreground/15 p-4">
      <div className="flex items-start gap-2.5">
        <Diamond lane={lane} faded />
        <p className="font-medium text-muted-foreground">{name}</p>
      </div>
      <p className="mt-auto text-xs text-muted-foreground">Queued</p>
    </div>
  )
}

function AgentCard({ lane, name, steps, profile, running, enter, reveal }: {
  lane: number
  name: string
  steps: TraceItem[]
  profile?: DrugProfile
  running: boolean
  enter: boolean
  reveal: boolean
}) {
  const done = steps.length + (profile ? 1 : 0)
  return (
    <article
      aria-label={`${name} agent`}
      className={cn(
        'flex min-h-[29rem] flex-col rounded-xl bg-card ring-1 ring-foreground/10 backdrop-blur-md',
        // Dealt onto its slot: a small tilt that alternates by lane, settling on a spring. Reduced motion keeps only the fade.
        enter && 'animate-in fade-in fill-mode-both duration-200 motion-safe:duration-[800ms] motion-safe:slide-in-from-bottom-6 motion-safe:zoom-in-95',
        enter && (lane % 2 ? 'motion-safe:spin-in-2' : 'motion-safe:spin-in-[-2deg]'),
      )}
      style={enter ? ({ '--tw-ease': SPRING, '--tw-animation-delay': `${lane * 60}ms` } as CSSProperties) : undefined}
    >
      <header className="flex items-start gap-2.5 px-4 pt-4">
        <Diamond lane={lane} />
        <h3 className="min-w-0 flex-1 font-medium leading-snug text-pretty">{name}</h3>
        <span className="flex shrink-0 items-center gap-1 pt-0.5 text-xs text-muted-foreground tabular-nums">
          {profile ? (
            <>
              <Check
                className={cn('size-3.5 text-foreground', reveal && 'animate-in fade-in fill-mode-both delay-300 duration-300 motion-safe:zoom-in-150')}
                style={reveal ? ({ '--tw-ease': EASE_OUT } as CSSProperties) : undefined}
                aria-hidden
              />
              Done
            </>
          ) : running ? (
            <>
              <Loader2 className="size-3 animate-spin" aria-hidden /> Step {done + 1} of {PHASES.length}
            </>
          ) : (
            `Step ${done} of ${PHASES.length}`
          )}
        </span>
      </header>

      <div className="min-h-[15.5rem] px-4 pt-3 pb-4">
        {profile ? <Profile profile={profile} reveal={reveal} /> : <Sketch done={done} />}
      </div>

