            status={i < done ? 'done' : i === done && running ? 'running' : 'pending'}
          />
        ))}
      </ol>
    </article>
  )
}

/** The finished profile. Rendered verbatim from the agent's output. */
function Profile({ profile, reveal }: { profile: DrugProfile; reveal: boolean }) {
  // Rows write in top to bottom, 50ms apart.
  const row = (i: number) =>
    reveal
      ? {
          className: 'animate-in fade-in fill-mode-both duration-300 motion-safe:slide-in-from-bottom-1',
          style: { '--tw-ease': EASE_OUT, '--tw-animation-delay': `${i * 50}ms` } as CSSProperties,
