          <dd className="mt-1">{profile.modality}</dd>
        </div>
        <div {...row(3)}>
          <dt className="text-muted-foreground">Constraints</dt>
          <dd>
            <ul className="mt-1 space-y-1">
              {profile.constraints.map((c) => (
                <li key={c} className="flex gap-1.5">
                  <span aria-hidden className="mt-[0.5em] size-1 shrink-0 rounded-full bg-foreground/30" />
                  {c}
                </li>
              ))}
            </ul>
          </dd>
        </div>
      </dl>
    </>
  )
}

/** The profile while it's being written: the same form, its lines drawing in as each step lands. */
function Sketch({ done }: { done: number }) {
  const line = (width: string, after: number, i: number) => (
    <span
      key={i}
      className={cn(
        'block h-2 origin-left rounded-full bg-foreground/[0.08] transition-transform duration-500 motion-reduce:transition-none',
