}

/** One step of the agent's work. Opens to show exactly what the agent did. */
function PhaseRow({ label, item, status }: { label: string; item?: TraceItem; status: 'pending' | 'running' | 'done' }) {
  const [open, setOpen] = useState(false)
  const body = (
