 * covered; otherwise pixels sparkle in and out. Plays once on mount; skipped under reduced motion.
 */
function Pixels({ color, cover = false, delay = 0 }: { color: string; cover?: boolean; delay?: number }) {
  const ref = useRef<HTMLCanvasElement>(null)
  const [finished, setFinished] = useState(() => matchMedia('(prefers-reduced-motion: reduce)').matches)
  useEffect(() => {
    const canvas = ref.current
    const ctx = canvas?.getContext('2d')
