      onPointerMove={track}
      className={cn('group relative isolate overflow-hidden rounded-xl bg-card ring-1 ring-border backdrop-blur-md', entrance.className)}
      style={entrance.style}
    >
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0 -z-10 opacity-0 transition-opacity duration-300 group-hover:opacity-100"
        style={{ background: `radial-gradient(420px circle at var(--x, 50%) var(--y, 0%), ${color}24, transparent 70%)` }}
      />

      <div className={cn(LANE_GRID, 'min-h-32')}>
        <div>
          <div className="flex items-start gap-2.5">
            <Diamond lane={lane} />
            <div className="min-w-0">
              <h3 className="font-medium leading-snug text-balance">{name}</h3>
              <p className="mt-1 flex items-center gap-1 text-xs text-muted-foreground tabular-nums">
                {profile ? (
                  <>
                    <Check
                      className={cn('size-3.5 text-foreground', reveal && 'animate-in fade-in fill-mode-both delay-300 duration-300 motion-safe:zoom-in-150')}
                      style={reveal ? ({ '--tw-ease': EASE_OUT } as CSSProperties) : undefined}
                      aria-hidden
                    />
                    Done
                  </>
                ) : (
                  `Step ${Math.min(done + (running ? 1 : 0), PHASES.length)} of ${PHASES.length}`
                )}
              </p>
            </div>
          </div>
          <StepBar color={color} done={done} running={running} open={open} toggle={() => setOpen((v) => !v)} />
        </div>
        {profile ? <Profile profile={profile} reveal={reveal} /> : <Sketch done={done} />}
      </div>

      {open ? (
        <ol className="border-t border-border py-1.5" aria-label="Agent steps">
          {PHASES.map((ph, i) => (
            <PhaseRow
              key={ph.type}
              label={ph.label}
              item={steps.find((s) => s.step.type === ph.type)}
              status={i < done ? 'done' : i === done && running ? 'running' : 'pending'}
            />
          ))}
        </ol>
      ) : null}
    </article>
  )
}

/** The finished profile, as three lane columns. Rendered verbatim from the agent's output. */
function Profile({ profile, reveal }: { profile: DrugProfile; reveal: boolean }) {
  return (
    <>
      <p {...arrive(reveal, 0)} className={cn('max-w-prose leading-snug text-pretty', arrive(reveal, 0).className)}>{profile.hypothesis}</p>
      <dl {...arrive(reveal, 1)} className={cn('space-y-3 text-sm', arrive(reveal, 1).className)}>
        <div>
          <dt className="text-xs text-muted-foreground">Targets</dt>
          <dd className="mt-1.5 flex flex-wrap gap-1 text-xs">
            {profile.targets.map((t) => (
              <span key={t} className="rounded-md bg-foreground/5 px-1.5 py-0.5 font-medium">{t}</span>
            ))}
          </dd>
        </div>
        <div>
          <dt className="text-xs text-muted-foreground">Modality</dt>
          <dd className="mt-1">{profile.modality}</dd>
        </div>
      </dl>
      <dl {...arrive(reveal, 2)} className={cn('text-sm', arrive(reveal, 2).className)}>
        <dt className="text-xs text-muted-foreground">Constraints</dt>
        <dd>
          <ul className="mt-1.5 space-y-1">
            {profile.constraints.map((c) => (
              <li key={c} className="flex gap-1.5">
                <span aria-hidden className="mt-[0.55em] size-1 shrink-0 rounded-full bg-foreground/30" />
                {c}
              </li>
            ))}
          </ul>
        </dd>
      </dl>
    </>
  )
}

